import{_ as t,c as n,o as l,j as e,a as s}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易图通变","description":"易图通变 - 易图通变","frontmatter":{"title":"易图通变","description":"易图通变 - 易图通变"},"headers":[],"relativePath":"zh/classics/yitu-tongbian/001.md","filePath":"zh/classics/yitu-tongbian/001.md"}'),i={name:"zh/classics/yitu-tongbian/001.md"};function r(o,a,c,p,d,u){return l(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"易图通变",tabindex:"-1"},[s("易图通变 "),e("a",{class:"header-anchor",href:"#易图通变","aria-label":"Permalink to “易图通变”"},"​")],-1),e("p",null,"钦定四库全书经部一",-1),e("p",null,"易类易筮通变提要",-1),e("p",null,"臣 等谨案：易图通变五卷，易筮通变三卷，宋雷思齐撰。思齐字齐贤，临川人。宋亡之后，弃儒服为道士，居乌石观。后终于广信。事迹具袁桷所撰墓志铭。是编前有揭徯斯序，称所著有老子本义、庄子旨义数十卷及和陶诗三卷。吴全节序又称其有文集二十卷。今皆未见，惟此二书存。其易图通变自序谓河图之数，以八卦成列，相荡相错，恭天两地，参伍以变其数实为四十，而以其十五会通于中。所述河图洛书参天两地倚数之图、错综会变等图，及河图遗论，大旨以天一为坎，地二为坤，天三为震，地四为巽，天七为兑，地六为乾，天九为离，地八为艮，而五十则为虚数。其说虽与先儒不同，而按以出震齐巽之义，亦颇相脗合。林至易裨傅序所谓易道变化不穷，得其一端，皆足以为说者也。其易筮通变凡五篇，一曰卜筮，二曰立卦，三曰九六，四曰衍数，五曰命蓍，亦多自出新意，不主旧法。白云霁道藏目录载二书于太元部若字号中，盖图书之学，实出道家，思齐又本道士衍说之，以附于易，固亦有由云。乾隆四十六年十二月恭校上。",-1),e("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。钦定四库全书易图通变序：",-1),e("p",null,"道德数千言，吾教之所独尊，古今未有能废之者。然传注层出，渺茫丛惑，莫适指归，徒见多岐之纷纷也。雷思齐嗜学有要，精研是书，探核本旨，为之传释，合儒老之所同，历诋其所异，条分绪别，终始一贯，不翅入老氏之室，避之席，以相授受也。其将学是者，终究其说，知其玄之玄，而不昧其所向，传之将来，庶几于吾教非小补也。至元丙辰，嗣天师简斋张宗演序。",-1),e("p",null,"雷先生思齐，字齐贤，临川之高士也。遭宋亡，独居空山之中，著易图筮通变义、老子本义、庄子旨义凡数十卷，和陶诗三卷。去儒服，称黄冠师，与故淳安令曾公子良、今翰林学士吴公澄相友善。四方名士大夫慕其人，往往以书疏自通。或闻其讲学，莫不爽然自失。故翰林侍讲学士袁公桷，博雅君子也，称其所著书援据精切，感厉奋发，合神以穷变，尽变以翼道。且曰：「知齐贤不如是，齐贤之意不明。」方今天下称为斯文宗主，莫先吴公；天下称善著书，莫先吴公。亦曰：「与谈老子甚契。」又称其诗精深工致，豪健奇杰，有杜韩风。盖皆以为知言。呜呼！古称虞卿非穷愁不能著书，太史公世掌天官，使不遇祸，史记不作。夫求雷先生之志，读雷先生之书，遑与世俗道哉！遑与世俗道哉！余读其所著之书，想其为人几五十年。今又得其诗文二十卷于其徒孙傅性真与周惟和传入京师来，因识以辞。至顺三年三月揭傒斯书昔世祖皇帝既定江南，首召三十六代天师入朝。未几，天师奉旨掌道教还山，遂礼请先生为玄学讲师，以训迪后人。余时虽幼，而有志于学，遂受学于先生。先生尝诲余曰：「文章于道，一技耳。人之为学，将以明斯道也。不明斯道，不足以为圣贤之学矣。」余由是日知所省，益自奋发。及弱冠，入侍先师开府公于朝，遂不得事先生以终学焉。先生尝注易图筮通变义、老子本义、庄子旨义凡数十卷，诗文二十卷。至顺二年秋，先生之徒弟傅性真遣徒孙周惟和持所著诸书来京师示余，且曰：「先生所注之书，虽有黄公震、曾公子良、吴公澄为之序，而未得公一言以发明之，敢以为请。」余曰：「嗟夫！先生之殁迨三十年矣，今不可得见，得见所注之书，斯可矣。然先生之学，岂所注之书可能尽哉？后之观者考诸书，则知先生之学诚不止若是也。」余今且老，久留于朝，常欲集先生诸文而序之，未果也。今诸文既已成编，又岂敢嘿嘿无一言以发明先生之学哉？故续为之序。先生讳思齐，字齐贤，学者尊之曰「空山先生」，抚之临川人也。至顺三年岁在壬申六月旦日，吴全节序。",-1),e("p",null,"河图，八卦是也。图之出，圣人则之。庖牺氏仰观象，俯观法，近取身，远取物，以通神明之德，类万物之情，始因之画八卦以作易者也。孔子谓「其则之」，岂欺我哉？图之数以八卦成列，相荡相错，参天两地，参伍以变，皆自然而然。后世不本其数，实惟四十，而以其十五会通于中，乃妄计天地之数五十有五，以意增制于四十之外，以求其合，幸其中，故愈说愈迷，纷纷迄今。余因潜心有年，备讨众说，独识先圣之指归，遂作通变传，以与四方千载学易者，同究于真是焉。兼筮法亦乖素旨，附见后篇，求古同志，宜能明其非敢诬也。大元大德庚子九月，临川道士雷思齐齐贤序。",-1)])])}const f=t(i,[["render",r]]);export{_ as __pageData,f as default};
